import pyomo.environ as pyo

DATA = {
    "patients_required": 320,
    "vehicles": ["ambulance", "van"],
    "capacity": {"ambulance": 20, "van": 15},
    "cost": {"ambulance": 820, "van": 550},
    "van_shift_fraction_max": 0.60,
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.V = pyo.Set(initialize=d["vehicles"])

    model.shifts = pyo.Var(
        model.V,
        within=pyo.NonNegativeIntegers,
    )

    def obj_rule(m):
        return sum(d["cost"][v] * m.shifts[v] for v in m.V)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    def demand_rule(m):
        return sum(d["capacity"][v] * m.shifts[v] for v in m.V) >= d["patients_required"]

    model.demand = pyo.Constraint(rule=demand_rule)

    def van_limit_rule(m):
        f = d["van_shift_fraction_max"]
        return m.shifts["van"] <= f * sum(m.shifts[v] for v in m.V)

    model.van_limit = pyo.Constraint(rule=van_limit_rule)

    return model
